763      static private boolean validOnDeclaredDomains(Overload o1, Overload o2, Collection<Overload> all) {
764          SingleFcn f1 = o1.getFn();
765          SingleFcn f2 = o2.getFn();
766          if (ownGeneric(f1) && ownGeneric(f2)) return genericPairValid(o1, o2, all);
767          Overload gen;
768          Overload plain;
769          if (ownGeneric(f1) && !(f2 instanceof GenericFunctionOrMethod)) {
770              gen = o1;
771              plain = o2;
772          } else if (ownGeneric(f2) && !(f1 instanceof GenericFunctionOrMethod)) {
773              gen = o2;
774              plain = o1;
775          } else {
776              return false;
777          }
778          if (hasRest(gen.getParams()) || hasRest(plain.getParams())) return false;
779          if (gen.getParams().size() != plain.getParams().size()) return false;
780          try {
781              SingleFcn g = gen.getFn();
782              SingleFcn p = plain.getFn();
783              boolean plainInside = instanceHolding(g, plain.getParams(), true) != null;
784              boolean genInside = declaredBelow(g, null, p, p, true);
785              if (plainInside && genInside) return false;
786              if (plainInside) return p.getRange().subtypeOf(g.getRange());
787              if (genInside) return g.getRange().subtypeOf(p.getRange());
788              return genericOverlapCovered(gen, plain, all);
789          }
790          catch (FortressException ex) {
791              return false;
792          }
793      }

